package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// New returns a full bucket. capacity must be > 0, rate must be > 0, clock must be non-nil.
func New(capacity int, rate float64, clock Clock) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	now := clock.Now()
	return &TokenBucket{
		capacity: float64(capacity),
		tokens:   float64(capacity),
		rate:     rate,
		last:     now,
		clock:    clock,
	}, nil
}

// NewReal returns a bucket using the system clock.
func NewReal(capacity int, rate float64) (*TokenBucket, error) {
	return New(capacity, rate, realClock{})
}

func (b *TokenBucket) refillLocked() {
	now := b.clock.Now()
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}

// AllowN consumes n tokens if available. n == 0 always succeeds; n < 0 always fails.
func (b *TokenBucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	if n == 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	if float64(n) > b.tokens {
		return false
	}
	b.tokens -= float64(n)
	return true
}

// Allow consumes one token.
func (b *TokenBucket) Allow() bool { return b.AllowN(1) }

// Tokens reports the current available tokens after refill.
func (b *TokenBucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	return b.tokens
}

// Capacity reports the configured maximum tokens.
func (b *TokenBucket) Capacity() int { return int(b.capacity) }
