// ratelimit.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

type Limiter struct {
	mu    sync.Mutex
	clock Clock
	rate  float64
	burst int
	tokens float64
	last  time.Time
}

func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if math.IsNaN(rate) || math.IsInf(rate, 0) || rate <= 0 {
		return nil, errors.New("ratelimit: rate must be finite and > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	now := clock.Now()
	return &Limiter{
		clock:  clock,
		rate:   rate,
		burst:  burst,
		tokens: float64(burst),
		last:   now,
	}, nil
}

func NewDefault(rate float64, burst int) (*Limiter, error) {
	return New(rate, burst, realClock{})
}

func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	if n == 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if elapsed := now.Sub(l.last).Seconds(); elapsed > 0 {
		l.tokens = math.Min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}
	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}
