package ratelimit

import (
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock(t time.Time) *fakeClock { return &fakeClock{t: t} }

func (f *fakeClock) Now() time.Time {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.t
}

func (f *fakeClock) Advance(d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.t = f.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	tests := []struct {
		name  string
		rate  float64
		burst int
		clock Clock
		want  bool
	}{
		{"nil clock", 1, 1, nil, true},
		{"zero rate", 0, 1, clk, true},
		{"negative rate", -1, 1, clk, true},
		{"NaN rate", 0.0/1.0*0, 1, clk, true}, // replaced below
		{"zero burst", 1, 0, clk, true},
		{"negative burst", 1, -1, clk, true},
		{"valid", 1, 1, clk, false},
	}
	tests[3].rate = nan()
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := New(tt.rate, tt.burst, tt.clock)
			if (err != nil) != tt.want {
				t.Fatalf("New() err = %v, wantErr = %v", err, tt.want)
			}
		})
	}
}

func nan() float64 {
	return 0.0 / 1.0 * (1.0 / 0.0)
}

func TestAllowN(t *testing.T) {
	type step struct {
		advance time.Duration
		n       int
		want    bool
	}
	tests := []struct {
		name  string
		rate  float64
		burst int
		steps []step
	}{
		{"burst exhausted", 1, 2, []step{{0, 2, true}, {0, 1, false}}},
		{"refill over time", 10, 5, []step{{0, 5, true}, {100 * time.Millisecond, 1, true}, {0, 1, false}}},
		{"partial refill", 2, 1, []step{{0, 1, true}, {250 * time.Millisecond, 1, false}, {250 * time.Millisecond, 1, true}}},
		{"zero and negative", 1, 1, []step{{0, 0, true}, {0, -1, false}}},
		{"fractional tokens", 4, 1, []step{{0, 1, true}, {125 * time.Millisecond, 1, false}, {125 * time.Millisecond, 1, true}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clk := newFakeClock(time.Unix(0, 0))
			l, err := New(tt.rate, tt.burst, clk)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tt.steps {
				clk.Advance(s.advance)
				if got := l.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowNConcurrent(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, err := New(1000, 100, clk)
	if err != nil {
		t.Fatal(err)
	}
	var allowed atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(1) {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if allowed.Load() != 100 {
		t.Fatalf("allowed = %d, want 100", allowed.Load())
	}
}
